import { createRevealPreparation } from '../app/reveal-preparation.js';
import { writePlayerStorage } from '../app/browser-storage.js';
// /app/components/app-sdgnrs-redemptions.js — durable sDGNRS redemption tray.
//
// A live-game sDGNRS burn only SUBMITS a delayed redemption. Once the period
// roll lands, mineRun's Redemption stage settles it (audit 18490c6fe) and
// creates/resolves the redemption lootbox. After game over the owner claims
// directly (claimRedemption). This headless controller keeps pending redemptions
// visible in the fixed bottom tray, survives refreshes, and can replay a
// settled redemption from its immutable transaction receipt. From audit
// 01f11477c a row's `periodIndex` is the redemption BATCH id.

import { CHAIN, CONTRACTS } from '../app/chain-config.js';
import { revealedBoxesKey } from '../app/lootbox-storage.js';
import { getProvider } from '../app/contracts.js';
import { subscribe } from '../app/store.js';
import { registerComponentPoll, DISPLAY_POLL_MS } from '../app/component-poll.js';
import { permissionlessReadProvider, readTransactionReceipt } from '../app/read-provider.js';
import {
  claimSdgnrsRedemption,
  discoverSdgnrsRedemptions,
  formatSdgnrsRedemptionAmount,
  isSdgnrsRedemptionKey,
  parseSdgnrsRedemptionReceipt,
  readSdgnrsRedemptionState,
  SDGNRS_REDEMPTION_SUBMITTED_EVENT,
} from '../app/sdgnrs.js';
import { enrichLootboxBoonLegs, parseOpenLegsFromReceipt } from '../app/lootbox-legs.js';
import { clearPendingActions, publishPendingActions } from '../app/pending-actions.js';
import {
  LOOTBOX_REVEAL_ABORT_EVENT,
  LOOTBOX_REVEAL_COMPLETE_EVENT,
  queueReveal,
  prepareReveal,
} from './reveal-queue.js';

const PENDING_SOURCE = 'sdgnrs-redemptions';
// 30s like the other Pending-tray watchers (whale-pass, launch-claims):
// redemption maturity is period-boundary-based, and the previous 12s cadence
// made this the fastest poll in the app for a state that moves the slowest —
// each tick re-running the (incremental) 120k-block log discovery plus a
// per-period read pair.
const POLL_MS = DISPLAY_POLL_MS; // Fallback for changes made outside this tab.
const MAX_RECENT_RESULTS = 6;

export function pendingSdgnrsRedemptionsKey(chainId, address) {
  return `pending-sdgnrs-redemptions:${chainId}:${String(address || '').toLowerCase()}`;
}

export function revealedSdgnrsRedemptionsKey(chainId, address) {
  return `revealed-sdgnrs-redemptions:${chainId}:${String(address || '').toLowerCase()}`;
}

function _readJsonArray(key) {
  try {
    const parsed = JSON.parse(localStorage.getItem(key) || '[]');
    return Array.isArray(parsed) ? parsed : [];
  } catch (_e) {
    return [];
  }
}

function _readPeriods(address) {
  return [...new Set(_readJsonArray(pendingSdgnrsRedemptionsKey(CHAIN.id, address))
    .map(Number)
    .filter(isSdgnrsRedemptionKey))];
}

function _writePeriods(address, periods) {
  if (!address) return;
  const key = pendingSdgnrsRedemptionsKey(CHAIN.id, address);
  const values = [...new Set((Array.isArray(periods) ? periods : [])
    .map(Number)
    .filter(isSdgnrsRedemptionKey))];
  try {
    if (values.length === 0) localStorage.removeItem(key);
    else writePlayerStorage(key, JSON.stringify(values));
  } catch (_e) { /* private mode */ }
}

/**
 * The seen-set key of a pending redemption. Batch ids restart at 1 on every deployment on this
 * chain, so a batch key names its sDGNRS contract: an earlier run's batch must not hide this
 * deployment's batch N.
 */
function _periodKey(periodIndex) {
  return `batch:${String(CONTRACTS.SDGNRS || '').toLowerCase()}:${Number(periodIndex)}`;
}

const _seenOverrides = new Map();
function _readSeen(address) {
  const key = revealedSdgnrsRedemptionsKey(CHAIN.id, address);
  const seen = new Set(_readJsonArray(key).map(String));
  for (const [id, value] of _seenOverrides.get(key) || []) {
    if (value) seen.add(id);
    else seen.delete(id);
  }
  return seen;
}

function _setSeen(address, keys, value) {
  if (!address) return;
  const key = revealedSdgnrsRedemptionsKey(CHAIN.id, address);
  const overrides = _seenOverrides.get(key) || new Map();
  for (const id of keys) if (id) overrides.set(String(id), value);
  _seenOverrides.set(key, overrides);
  writePlayerStorage(key, JSON.stringify([..._readSeen(address)]));
}

/**
 * Un-see a redemption the player never actually watched. The claim already
 * paid, so the only thing left is its presentation: once `tx:<hash>` is in the
 * seen set, discovery filters the row out for good. The overlay hands the id
 * back when its queue is dropped by the close button.
 */
function _unmarkSeen(address, ...keys) {
  _setSeen(address, keys, false);
}

function _markSeen(address, ...keys) {
  _setSeen(address, keys, true);
}

// Redemption lootboxes emit the same index-zero settlement legs as AFKing.
// Mark the transaction in the ordinary box controller's durable seen set so
// the claim receipt cannot be offered a second time as a generic lootbox.
function _markGenericBoxSeen(address, transactionHash) {
  if (!address || !transactionHash) return;
  try {
    const key = revealedBoxesKey(CHAIN.id, address);
    const seen = new Set(_readJsonArray(key).map(String));
    seen.add(`tx:${String(transactionHash).toLowerCase()}`);
    writePlayerStorage(key, JSON.stringify([...seen]));
  } catch (_e) { /* private mode */ }
}

function _reserveClaimResult(address, transactionHash) {
  if (!address || !transactionHash) return;
  const key = `tx:${String(transactionHash).toLowerCase()}`;
  _markGenericBoxSeen(address, transactionHash);
  try {
    document.dispatchEvent(new CustomEvent(LOOTBOX_REVEAL_COMPLETE_EVENT, {
      detail: { address: String(address).toLowerCase(), key },
    }));
  } catch (_e) { /* headless */ }
}

function _claimCards(claim) {
  if (!claim) return [];
  const legs = [];
  if (BigInt(claim.ethPayout ?? 0) > 0n) {
    legs.push({ legType: 'eth', amount: BigInt(claim.ethPayout), claimable: true });
  }
  if (BigInt(claim.flipPaid ?? 0) > 0n) {
    legs.push({ legType: 'flip', amount: BigInt(claim.flipPaid) });
  }
  return legs;
}

function _rowKey(row) {
  return row.type === 'claim'
    ? `tx:${String(row.transactionHash || '').toLowerCase()}`
    : _periodKey(row.periodIndex);
}

class AppSdgnrsRedemptions extends HTMLElement {
  #initialized = false;
  #address = null;
  #rows = [];
  #refreshing = false;
  #poll = null;
  #unsubscribe = null;
  #submissionListener = null;
  #revealAbortListener = null;
  #revealCompleteListener = null;
  // Seen-keys handed to the overlay, by presentation id, so an abort can put
  // the redemption back on the tray. Cleared as soon as it is restored.
  #stagedSeenKeys = new Map();
  #preparedClaims = createRevealPreparation({ limit: 8 });

  connectedCallback() {
    if (this.#initialized) return;
    this.#initialized = true;
    this.hidden = true;
    this.#submissionListener = (event) => this.#onSubmission(event?.detail);
    document.addEventListener(SDGNRS_REDEMPTION_SUBMITTED_EVENT, this.#submissionListener);
    this.#revealAbortListener = (event) => {
      const ids = Array.isArray(event?.detail?.presentationIds)
        ? event.detail.presentationIds : [];
      let restored = false;
      for (const id of ids) {
        const staged = this.#stagedSeenKeys.get(String(id));
        if (!staged) continue;
        this.#stagedSeenKeys.delete(String(id));
        _unmarkSeen(staged.address, ...staged.keys);
        restored = true;
      }
      if (restored) void this.#refresh();
    };
    this.#revealCompleteListener = event => {
      const id = String(event.detail?.presentationId || '');
      const staged = this.#stagedSeenKeys.get(id);
      if (!staged) return;
      _markSeen(staged.address, ...staged.keys);
      this.#stagedSeenKeys.delete(id);
    };
    document.addEventListener(LOOTBOX_REVEAL_COMPLETE_EVENT, this.#revealCompleteListener);
    document.addEventListener(LOOTBOX_REVEAL_ABORT_EVENT, this.#revealAbortListener);
    this.#unsubscribe = subscribe('connected.address', (address) => {
      this.#address = address ? String(address).toLowerCase() : null;
      this.#rows = this.#address
        ? _readPeriods(this.#address).map((periodIndex) => ({
            type: 'period', periodIndex, state: 'waiting', ready: false,
          }))
        : [];
      this.#publish();
      if (this.#address) void this.#refresh();
    });
    this.#poll = registerComponentPoll(() => this.#refresh(), POLL_MS, { owner: this, transactionDomains: ['sdgnrs'], refreshOn: ['transaction', 'day', 'phase'] });
  }

  disconnectedCallback() {
    this.#initialized = false;
    this.#address = null;
    this.#rows = [];
    if (typeof this.#poll === 'function') this.#poll();
    this.#poll = null;
    try { this.#unsubscribe?.(); } catch (_e) { /* defensive */ }
    this.#unsubscribe = null;
    document.removeEventListener(LOOTBOX_REVEAL_COMPLETE_EVENT, this.#revealCompleteListener);
    this.#revealCompleteListener = null;
    if (this.#submissionListener) {
      if (this.#revealAbortListener) {
        try { document.removeEventListener(LOOTBOX_REVEAL_ABORT_EVENT, this.#revealAbortListener); }
        catch (_e) { /* defensive */ }
        this.#revealAbortListener = null;
      }
      try { document.removeEventListener(SDGNRS_REDEMPTION_SUBMITTED_EVENT, this.#submissionListener); }
      catch (_e) { /* defensive */ }
    }
    this.#submissionListener = null;
    clearPendingActions(PENDING_SOURCE);
  }

  #onSubmission(detail) {
    if (!this.#address) return;
    if (String(detail?.player || '').toLowerCase() !== this.#address) return;
    const periodIndex = Number(detail?.periodIndex);
    if (!Number.isInteger(periodIndex) || periodIndex < 0) return;
    const periods = new Set(_readPeriods(this.#address));
    periods.add(periodIndex);
    _writePeriods(this.#address, [...periods]);
    let submittedAmount = 0n;
    try { submittedAmount = BigInt(detail?.sdgnrsAmount ?? 0); }
    catch (_e) { /* keep the durable period even if an old event omitted amount */ }
    const existing = this.#rows.find((row) => (
      row.type === 'period' && row.periodIndex === periodIndex
    ));
    if (existing) {
      existing.sdgnrsAmount = BigInt(existing.sdgnrsAmount ?? 0) + submittedAmount;
    } else {
      this.#rows.push({
        type: 'period', periodIndex, state: 'waiting', ready: false,
        sdgnrsAmount: submittedAmount,
      });
    }
    this.#publish();
    void this.#refresh();
  }

  async #refresh() {
    if (this.#refreshing || !this.#address) return;
    if (document.visibilityState && document.visibilityState !== 'visible') return;
    this.#refreshing = true;
    const owner = this.#address;
    try {
      const stored = _readPeriods(owner);
      const discovered = await discoverSdgnrsRedemptions({
        player: owner,
        periodIndexes: stored,
      });
      if (this.#address !== owner) return;
      const states = new Map();
      for (const state of discovered?.periods || []) {
        if (!state?.exists) continue;
        const periodIndex = Number(state.periodIndex);
        const prior = states.get(periodIndex);
        states.set(periodIndex, {
          ...prior,
          ...state,
          sdgnrsAmount: state.sdgnrsAmount ?? prior?.sdgnrsAmount ?? null,
        });
      }
      const seen = _readSeen(owner);
      for (const staged of this.#stagedSeenKeys.values()) {
        if (staged.address === owner) for (const key of staged.keys) seen.add(key);
      }
      const periodRows = [...states.values()]
        .filter((state) => !seen.has(_periodKey(state.periodIndex)))
        .map((state) => ({
          type: 'period',
          periodIndex: state.periodIndex,
          roll: state.roll,
          sdgnrsAmount: state.sdgnrsAmount ?? null,
          state: state.ready ? 'ready' : 'waiting',
          ready: state.ready,
          settling: Boolean(state.settling),
          open: Boolean(state.open),
        }));
      _writePeriods(owner, [...states.keys()]);

      const claimRows = (Array.isArray(discovered?.claims) ? discovered.claims : [])
        .filter((claim) => claim.transactionHash
          && !seen.has(`tx:${String(claim.transactionHash).toLowerCase()}`))
        .slice(0, MAX_RECENT_RESULTS)
        .map((claim) => ({ ...claim, type: 'claim', state: 'ready', ready: true }));
      for (const claim of claimRows) _reserveClaimResult(owner, claim.transactionHash);
      this.#rows = [...periodRows, ...claimRows];
      this.#publish();
    } catch (_e) {
      // Keep the last durable rows visible; the next poll retries.
    } finally {
      this.#refreshing = false;
    }
  }

  async #receipt(transactionHash) {
    const provider = permissionlessReadProvider(getProvider());
    if (!provider || typeof provider.getTransactionReceipt !== 'function') return null;
    try { return await readTransactionReceipt(transactionHash, { provider }); }
    catch (_e) { return null; }
  }

  #claimSequence(row, owner, legs) {
    return {
      kind: 'lootbox', title: 'sDGNRS REDEMPTION', lootboxIndex: 0, legs,
      presentationId: `sdgnrs-redemption:${owner}:${_rowKey(row)}`,
      lootboxRelease: { address: owner, key: _rowKey(row) },
    };
  }

  #prepareClaim(row, owner, suppliedReceipt = null, suppliedClaim = null) {
    const key = `${CONTRACTS.GAME}:${owner}:${row.transactionHash || suppliedReceipt?.hash || _rowKey(row)}`;
    return this.#preparedClaims.get(key, async () => {
      const receipt = suppliedReceipt || await this.#receipt(row.transactionHash);
      if (!receipt) return null;
      const parsed = parseSdgnrsRedemptionReceipt(receipt, owner);
      const claim = parsed.claims.at(-1) || suppliedClaim || row;
      const boxLegs = await enrichLootboxBoonLegs(parseOpenLegsFromReceipt(receipt, owner), {
        player: owner, blockNumber: receipt.blockNumber ?? null,
      });
      const legs = [..._claimCards(claim), ...boxLegs];
      return legs.length ? { receipt, claim, legs } : null;
    });
  }

  async #run(row) {
    if (!this.#address || row.state !== 'ready') return;
    const owner = this.#address;
    row.state = 'busy';
    this.#publish();
    try {
      let receipt;
      let claim = row.type === 'claim' ? row : null;
      if (row.type === 'period') {
        const exact = await readSdgnrsRedemptionState({
          player: owner,
          periodIndex: row.periodIndex,
          fresh: true,
        });
        if (!exact?.ready) throw new Error('This sDGNRS redemption is still waiting for RNG.');
        const result = await claimSdgnrsRedemption({
          player: owner,
          periodIndex: row.periodIndex,
        });
        receipt = result.receipt;
        claim = result.claim;
      }
      const prepared = await this.#prepareClaim(row, owner, receipt, claim);
      if (!prepared) throw new Error('The sDGNRS result is still syncing. Try again shortly.');
      ({ receipt, claim } = prepared);
      const { legs } = prepared;
      if (this.#address !== owner) return false;
      const transactionHash = String(
        receipt?.hash || receipt?.transactionHash || claim?.transactionHash || row.transactionHash || '',
      ).toLowerCase();
      const seenKeys = [_rowKey(row)];
      if (row.type === 'period') seenKeys.push(_periodKey(row.periodIndex));
      if (transactionHash) seenKeys.push(`tx:${transactionHash}`);
      const presentationId = `sdgnrs-redemption:${owner}:${_rowKey(row)}`;
      const accepted = queueReveal(this.#claimSequence(row, owner, legs));
      if (!accepted) throw new Error('The sDGNRS result could not be displayed.');
      this.#stagedSeenKeys.set(presentationId, { address: owner, keys: seenKeys });
      _reserveClaimResult(owner, transactionHash);
      const periods = _readPeriods(owner).filter((period) => period !== Number(row.periodIndex));
      _writePeriods(owner, periods);
      this.#rows = this.#rows.filter((candidate) => _rowKey(candidate) !== _rowKey(row));
      this.#publish();
      void this.#refresh();
    } catch (error) {
      row.state = 'ready';
      this.#publish();
      throw error;
    }
  }

  #publish() {
    if (!this.#address) {
      clearPendingActions(PENDING_SOURCE);
      return;
    }
    publishPendingActions(PENDING_SOURCE, this.#rows.map((row) => {
      const ready = row.state === 'ready';
      const compactAmount = row.sdgnrsAmount != null && BigInt(row.sdgnrsAmount) > 0n
        ? `${formatSdgnrsRedemptionAmount(row.sdgnrsAmount)} sDGNRS`
        : '';
      return {
        id: `sdgnrs-redemption:${_rowKey(row)}`,
        dismissScope: this.#address,
        kind: 'lootbox',
        kindLabel: 'sDGNRS REDEMPTION',
        label: `${compactAmount ? `${compactAmount} ` : ''}REDEMPTION`,
        amountLabel: compactAmount,
        lootboxLabel: 'REDEMPTION',
        compact: true,
        shortLabel: row.type === 'claim' ? 'View result' : 'Claim & open',
        detail: row.state === 'busy'
          ? row.type === 'claim' ? 'Loading result' : 'Claiming on-chain'
          : ready
            ? row.type === 'claim' ? 'Resolved · ready to view' : `RNG landed${row.roll ? ` · ${row.roll}%` : ''}`
            : row.settling
              ? `RNG landed${row.roll ? ` · ${row.roll}%` : ''} · settles with the next Mine FLIP`
              : row.open
                ? 'Waiting for the next RNG request to price it'
                : 'Waiting for the RNG result',
        state: row.state,
        resolved: row.type === 'claim',
        autoOpen: row.type === 'claim' && ready,
        pinned: true,
        progress: row.state === 'waiting' ? 'indeterminate' : null,
        order: 18,
        chronology: Number(row.periodIndex ?? row.id ?? 0),
        prepareKey: row.transactionHash || _rowKey(row),
        prepare: async () => {
          if (row.type !== 'claim') return;
          const owner = this.#address;
          const prepared = await this.#prepareClaim(row, owner);
          if (!prepared) return false;
          await prepareReveal(this.#claimSequence(row, owner, prepared.legs));
        },
        run: () => this.#run(row),
      };
    }));
  }

  /** Test-only refresh hook. */
  async __refreshForTest() { await this.#refresh(); }
}

if (typeof customElements !== 'undefined' && !customElements.get('app-sdgnrs-redemptions')) {
  customElements.define('app-sdgnrs-redemptions', AppSdgnrsRedemptions);
}
